create extension if not exists pgcrypto;
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = timezone('utc', now()); return new; end $$;

create table if not exists public.profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id) on delete cascade, display_name text not null default '', timezone text not null default 'Asia/Shanghai', legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table if not exists public.user_settings (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id) on delete cascade, exam_name text not null default '距离考试', exam_date date not null default '2026-12-19', theme text not null default 'light' check(theme in ('light','dark')), ai_settings jsonb not null default '{}', legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table if not exists public.subjects (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, color text not null default '#386a5f', sort_order integer not null default 0, status text not null default 'active' check(status in ('active','archived')), legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, unique(user_id, legacy_id));
create table if not exists public.syllabus_nodes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid not null references public.subjects(id), parent_id uuid references public.syllabus_nodes(id), title text not null, kind text not null check(kind in ('chapter','topic')), status text not null default 'todo' check(status in ('todo','doing','done')), sort_order integer not null default 0, legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table if not exists public.plans (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, parent_plan_id uuid references public.plans(id), title text not null, period_type text not null check(period_type in ('month','week')), start_date date not null, end_date date not null, target text not null default '', legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, check(end_date >= start_date));
create table if not exists public.tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, plan_id uuid references public.plans(id), subject_id uuid references public.subjects(id), syllabus_node_id uuid references public.syllabus_nodes(id), title text not null, task_date date not null, period text not null default '全天', estimate_minutes integer not null default 0 check(estimate_minutes >= 0), actual_minutes integer not null default 0 check(actual_minutes >= 0), status text not null default 'todo' check(status in ('todo','doing','done')), sort_order integer not null default 0, completed_at timestamptz, legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, unique(user_id, legacy_id));
create table if not exists public.study_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, task_id uuid references public.tasks(id), subject_id uuid references public.subjects(id), started_at timestamptz not null, ended_at timestamptz not null, minutes integer not null check(minutes >= 0), source text not null check(source in ('timer','manual','legacy')), legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table if not exists public.notebook_folders (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid references public.subjects(id), name text not null, sort_order integer not null default 0, legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, unique(user_id, legacy_id));
create table if not exists public.notes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, folder_id uuid not null references public.notebook_folders(id), subject_id uuid references public.subjects(id), title text not null default '', html text not null default '', plain_text text not null default '', pinned boolean not null default false, source text not null default 'web' check(source in ('web','obsidian','legacy')), linked_dates date[] not null default '{}', conflict_of uuid references public.notes(id), legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, unique(user_id, legacy_id));
create table if not exists public.papers (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid not null references public.subjects(id), year integer not null, title text not null, total_score numeric not null default 100, legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table if not exists public.paper_attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, paper_id uuid not null references public.papers(id), attempt_no integer not null check(attempt_no > 0), status text not null check(status in ('planned','done')), score numeric, duration_minutes integer, completed_date date, legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, unique(user_id,paper_id,attempt_no));
create table if not exists public.knowledge_points (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid not null references public.subjects(id), title text not null, legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, unique(user_id,subject_id,title));
create table if not exists public.mistakes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid not null references public.subjects(id), knowledge_point_id uuid references public.knowledge_points(id), source_type text not null check(source_type in ('paper','mock','manual')), source_id uuid, question_ref text not null default '', error_reason text not null default '', weakness integer not null default 3 check(weakness between 1 and 5), next_review_date date, mastered boolean not null default false, legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table if not exists public.review_records (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, mistake_id uuid not null references public.mistakes(id), grade text not null check(grade in ('again','hard','good')), reviewed_at timestamptz not null, comment text not null default '', legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table if not exists public.mock_exams (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, exam_date date not null, total_score numeric not null default 0, target_score numeric not null default 0, rank integer, legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table if not exists public.mock_scores (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, mock_exam_id uuid not null references public.mock_exams(id), subject_id uuid not null references public.subjects(id), score numeric not null default 0, total_score numeric not null default 0, legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, unique(user_id,mock_exam_id,subject_id));
create table if not exists public.resources (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid references public.subjects(id), title text not null, kind text not null check(kind in ('course','pdf','question_bank','link')), url text not null default '', storage_path text, status text not null default 'active' check(status in ('active','archived')), legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table if not exists public.entity_links (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, source_type text not null, source_id uuid not null, target_type text not null, target_id uuid not null, legacy_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, unique(user_id,source_type,source_id,target_type,target_id));

do $$ declare t text; begin
  foreach t in array array['profiles','user_settings','subjects','syllabus_nodes','plans','tasks','study_sessions','notebook_folders','notes','papers','paper_attempts','knowledge_points','mistakes','review_records','mock_exams','mock_scores','resources','entity_links'] loop
    execute format('alter table public.%I enable row level security',t);
    execute format('drop policy if exists %I on public.%I',t||'_own_rows',t);
    execute format('create policy %I on public.%I for all to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id)',t||'_own_rows',t);
    execute format('drop trigger if exists %I on public.%I','trg_'||t||'_updated_at',t);
    execute format('create trigger %I before update on public.%I for each row execute function public.touch_updated_at()','trg_'||t||'_updated_at',t);
  end loop;
end $$;

insert into storage.buckets(id,name,public,file_size_limit) values('study-resources','study-resources',false,52428800) on conflict(id) do update set public=false;
drop policy if exists study_resources_select on storage.objects; drop policy if exists study_resources_insert on storage.objects; drop policy if exists study_resources_update on storage.objects; drop policy if exists study_resources_delete on storage.objects;
create policy study_resources_select on storage.objects for select to authenticated using(bucket_id='study-resources' and (storage.foldername(name))[1]=auth.uid()::text);
create policy study_resources_insert on storage.objects for insert to authenticated with check(bucket_id='study-resources' and (storage.foldername(name))[1]=auth.uid()::text);
create policy study_resources_update on storage.objects for update to authenticated using(bucket_id='study-resources' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='study-resources' and (storage.foldername(name))[1]=auth.uid()::text);
create policy study_resources_delete on storage.objects for delete to authenticated using(bucket_id='study-resources' and (storage.foldername(name))[1]=auth.uid()::text);
create index if not exists tasks_user_date_idx on public.tasks(user_id,task_date) where deleted_at is null;
create index if not exists notes_user_updated_idx on public.notes(user_id,updated_at desc) where deleted_at is null;
create index if not exists mistakes_user_review_idx on public.mistakes(user_id,next_review_date) where deleted_at is null and mastered=false;
create index if not exists mock_exams_user_date_idx on public.mock_exams(user_id,exam_date) where deleted_at is null;
